use crate::YYToken;
use std::io::{Read, stdin};
use std::str::from_utf8;

#[allow(unused)]
const INITIAL: usize = 0;
#[allow(unused)]
const INITIAL_BOL: usize = 1;

const READ_LEN: usize = 4096;

#[derive(Debug, PartialEq)]
enum LexerState {
    Error,
    Running,
    Eof,
}

#[derive(Debug)]
struct AcceptData {
    state: usize,
    buf_pos: usize,
}

pub struct YYLex<R: Read> {
    state: LexerState,
    action: isize,
    current_state: usize,
    start_condition: usize,
    buffer: Vec<u8>,
    buffer_position: usize,
    run_position: usize,
    trailing_end_pos: usize,
    trailing_action: isize,
    bol: bool,
    more: bool,
    accept_stack: Vec<AcceptData>,
    yycontinue: Box<dyn FnMut() -> Option<R>>,
    finished: bool,

    pub yyin: R,
    pub yytext: String,
    pub line_no: isize,
    pub col_no: isize,
}

#[allow(unused)]
impl<R: Read> YYLex<R> {
    pub fn new<F>(yyin: R, yycontinue: F) -> Self
    where
        F: FnMut() -> Option<R> + 'static,
    {
        Self {
            state: LexerState::Running,
            action: 0,
            current_state: 1,
            start_condition: 0,
            buffer: vec![],
            buffer_position: 0,
            run_position: 0,
            trailing_end_pos: 0,
            trailing_action: -1,
            bol: true,
            more: false,
            accept_stack: vec![],
            yycontinue: Box::new(yycontinue),
            yyin,
            yytext: String::new(),
            finished: false,
            line_no: 0,
            col_no: 0,
        }
    }
}

#[allow(unused)]
impl<R: Read> YYLex<R> {
    pub fn with_reader(yyin: R) -> Self {
        Self::new(yyin, || None)
    }
}

#[allow(unused)]
impl Default for YYLex<std::io::Stdin> {
    fn default() -> Self {
        Self::new(stdin(), || None)
    }
}

