impl<R: Read> Iterator for YYLex<R> {
    type Item = YYToken;

    fn next(&mut self) -> Option<Self::Item> {
        match self.yylex() {
            YYToken::yyeof if self.finished => {
                self.finished = true;
                Some(YYToken::yyeof)
            }
            YYToken::yyeof => None,
            tok => Some(tok),
        }
    }
}

fn comment<T: Read>(lex: &mut YYLex<T>)
{
    let mut c = lex.input();
    loop {
        while c != b'*' && c != 0 {
            c = lex.input();
        }
        let c1 = lex.input();
        if c1 != b'/' && c != 0 {
            lex.unput(c1);
        }
    }
}
